#include "../../src-tauri/src/live/sets_v2/chart.h"
static double chart_row(NSData *frame,int left,int right,unsigned *count){const uint8_t*p=frame.bytes;double sum=0;unsigned n=0;for(int y=0;y<200;y++)for(int x=left;x<right;x++){const uint8_t*q=p+(y*320+x)*4;if(q[0]>180&&q[1]>180&&q[2]<100&&q[3]>150){sum+=y;n++;}}*count=n;return n?sum/n:-1;}
static NSDictionary *chart_proof(NSString*out){
 const struct producer_chart_point low[]={{0,20,true},{1,20,true},{2,20,true}},high[]={{0,80,true},{1,80,true},{2,80,true}};
 struct producer_chart_spec spec={"temperature","city-one",0,0,2,0,100,0xff00ffff,0x00000000,650,3,.2,low,3};
 obs_source_t*a=producer_chart_create(320,200,&spec);require(a!=NULL,"native chart source created");spec.points=high;obs_source_t*b=producer_chart_create(320,200,&spec);require(b!=NULL,"next native chart source created");
 obs_enter_graphics();producer_chart_begin(b,a,1000);producer_chart_frame(b,1000);obs_leave_graphics();
 unsigned count=0;NSData*before=capture(b,320,200,320,200);double from=chart_row(before,100,220,&count);png(before,320,200,[out stringByAppendingPathComponent:@"chart-before-debug.png"]);fprintf(stderr,"CHART before row=%f count=%u\n",from,count);require(count>100&&from>150,"first frame retains previous committed curve");
 obs_enter_graphics();producer_chart_frame(b,1325);obs_leave_graphics();NSData*middle=capture(b,320,200,320,200);double mid=chart_row(middle,100,220,&count);require(count>100&&mid>85&&mid<115,"new readings interpolate on the presentation clock");
 NSData*held=capture(b,320,200,320,200);require([held isEqualToData:middle],"paused clock holds chart pixels");
 obs_enter_graphics();producer_chart_frame(b,1650);obs_leave_graphics();NSData*after=capture(b,320,200,320,200);double to=chart_row(after,100,220,&count);require(count>100&&to<50,"final curve reaches actual new readings");png(middle,320,200,[out stringByAppendingPathComponent:@"chart-midpoint.png"]);png(after,320,200,[out stringByAppendingPathComponent:@"chart-arrival.png"]);
 spec.scope="city-two";obs_source_t*city=producer_chart_create(320,200,&spec);require(city!=NULL,"new city chart");obs_enter_graphics();producer_chart_begin(city,a,1000);obs_leave_graphics();chart_row(capture(city,320,200,320,200),100,220,&count);require(count>100,"new city has valid curve");require(chart_row(capture(city,320,200,320,200),100,220,&count)<50,"different city never interpolates previous city values");
 const struct producer_chart_point gaps[]={{0,20,true},{1,0,false},{2,80,true}};spec.scope="gaps";spec.points=gaps;obs_source_t*gap=producer_chart_create(320,200,&spec);require(gap!=NULL,"null gaps accepted");chart_row(capture(gap,320,200,320,200),100,220,&count);require(count==0,"missing readings are gaps, not zero or connecting segments");
 struct producer_chart_point many[256];for(int i=0;i<256;i++)many[i]=(struct producer_chart_point){i,i%2?80:20,true};spec.points=many;spec.count=256;spec.x_max=255;spec.scope="bounded";obs_source_t*dense=producer_chart_create(320,200,&spec);require(dense!=NULL,"maximum bounded series");chart_row(capture(dense,320,200,320,200),295,315,&count);require(count>20,"native immediate batches render the end of a full series");
 spec.points=high;spec.count=3;spec.x_max=2;spec.kind=1;obs_source_t*area=producer_chart_create(320,200,&spec);require(area!=NULL,"area source");NSData*fill=capture(area,320,200,320,200);const uint8_t*px=fill.bytes;require(px[(130*320+160)*4+3]>0&&px[(130*320+160)*4+3]<100,"area has translucent gradient fill");
 spec.kind=2;obs_source_t*bars=producer_chart_create(320,200,&spec);require(bars!=NULL,"bar source");NSData*bar=capture(bars,320,200,320,200);px=bar.bytes;require(px[(130*320+160)*4+3]>100,"rain bars are native GPU geometry");png(bar,320,200,[out stringByAppendingPathComponent:@"chart-bars.png"]);
 spec.count=257;require(producer_chart_create(320,200,&spec)==NULL,"oversized input rejected before pointer access");

 obs_source_t*program=producer_set_v2_program_create(320,200);require(program!=NULL,"chart program owner");obs_set_output_source(0,program);require(producer_set_v2_program_pause(program,true),"pause program clock");
 require(producer_set_v2_program_prepare(program,a,1)&&producer_set_v2_program_chart(program,1,a)&&producer_set_v2_program_ready(program,1),"first chart take registered");capture(program,320,200,320,200);require(producer_set_v2_program_take(program,1,0,0),"first warmed chart take");capture(program,320,200,320,200);
 require(producer_set_v2_program_prepare(program,b,2)&&producer_set_v2_program_chart(program,2,b)&&producer_set_v2_program_ready(program,2),"live chart update registered");capture(program,320,200,320,200);require(producer_set_v2_program_take(program,2,0,0),"updated warmed chart take");NSData*programStart=capture(program,320,200,320,200);double programFrom=chart_row(programStart,100,220,&count);require(programFrom>150,"program carries displayed curve into the new data revision");
 require(producer_set_v2_program_pause(program,false),"resume program clock");usleep(350000);double programMid=chart_row(capture(program,320,200,320,200),100,220,&count);require(programMid>65&&programMid<140,"live program animates between received values");usleep(450000);chart_row(capture(program,320,200,320,200),100,220,&count);size_t builds=producer_chart_geometry_builds(b);capture(program,320,200,320,200);capture(program,320,200,320,200);require(producer_chart_geometry_builds(b)==builds,"steady chart reuses GPU geometry");obs_set_output_source(0,NULL);obs_source_release(program);
 obs_source_t *all[]={a,b,city,gap,dense,area,bars};for(int i=0;i<7;i++)obs_source_release(all[i]);
 for(int i=0;i<300&&producer_chart_live_count();i++)usleep(10000);require(producer_chart_live_count()==0,"all chart sources and geometry released");
 return @{@"ok":@YES,@"programAnimation":@YES,@"steadyGeometryReused":@YES,@"remainingCharts":@(producer_chart_live_count()),@"fromRow":@(from),@"midpointRow":@(mid),@"targetRow":@(to),@"pauseHoldsPixels":@YES,@"cityFence":@YES,@"missingValuesRemainGaps":@YES,@"maxPoints":@256,@"nativeLineAreaAndBar":@YES};
}
